// Create a synthetic io_uring_probe buffer to exercise io_uring_opcode_supported()
// This avoids any dependency on a live ring while still meeting the function's
// requirement that `p` points to a valid io_uring_probe-like memory layout.
unsigned ops_len = (unsigned)(*FUZZ_PARAM(unsigned int) % 64u) + 1u; // keep small
size_t probe_sz = sizeof(struct io_uring_probe) + ops_len * sizeof(struct io_uring_probe_op);
struct io_uring_probe *p = (struct io_uring_probe *)malloc(probe_sz);
if (!p) { FUZZ_BAIL(); }

// Initialize header fields
p->ops_len = (unsigned char)ops_len;               // number of entries in ops[]
p->last_op = (unsigned char)(*FUZZ_PARAM(unsigned int) % 256u); // arbitrary; may exceed ops_len
// Reserved fields can be zeroed for cleanliness
p->resv = 0;
p->resv2[0] = p->resv2[1] = p->resv2[2] = 0;

// Initialize ops[] conservatively with sequential op indices and random flags
for (unsigned i = 0; i < ops_len; ++i) {
    p->ops[i].op = (unsigned char)i; // make indexable for typical table lookups
    p->ops[i].flags = (unsigned short)(*FUZZ_PARAM(unsigned int));
    p->ops[i].resv = 0;
    p->ops[i].resv2 = 0;
}

// Choose an opcode to query; sometimes greater than last_op to exercise the 0-return path
int op = (int)(*FUZZ_PARAM(unsigned int) % ((unsigned)p->last_op + 2u));

// Invoke the target function
int ret = io_uring_opcode_supported(p, op);
(void)ret; // result is intentionally not asserted; function may legally return 0/!0

// Cleanup synthetic probe memory (the API expects io_uring_free_probe for real probes,
// but this buffer was locally allocated here; freeing directly is correct and safe).
free(p);

// Validation: The stub builds a minimally valid probe layout, calls the function with a
// fuzzed opcode spanning both <=last_op and >last_op cases, and frees the temporary buffer.

// Enforce that the ring is initialized before attempting a resize
if (!FUZZ_GET_ATTR_INT(ring, "initialized")) { FUZZ_BAIL(); }

// Prepare a small params structure; kernel may validate/modify these
struct io_uring_params params;
memset(&params, 0, sizeof(params));
// entries: keep modest; actual sizing is kernel-defined during resize path
params.sq_entries = (unsigned)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
params.cq_entries = (unsigned)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
params.flags      = (unsigned)(*FUZZ_PARAM(unsigned int));

// Attempt the resize operation
int rc = io_uring_resize_rings(ring, &params);
(void)rc; // May legitimately fail depending on kernel support and parameters

// Keep ring as output for further fuzzing
// Validation: Ensured initialized ring and provided a valid params pointer with sane small sizes.

// Both rings must be initialized for buffer cloning
if (!FUZZ_GET_ATTR_INT(dst, "initialized")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(src, "initialized")) { FUZZ_BAIL(); }

// Choose small ranges to avoid excessive work; kernel will validate
unsigned int dst_off = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u);
unsigned int src_off = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u);
unsigned int nr      = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u) + 1u;
unsigned int flags   = (unsigned)(*FUZZ_PARAM(unsigned int));

int rc = io_uring_clone_buffers_offset(dst, src, dst_off, src_off, nr, flags);
(void)rc; // May fail if no buffers are registered or flags/ranges invalid

// Output both rings (state may have changed if operation succeeded)
// Validation: Checked initialization and passed constrained offsets/count.

// Internal variant; same constraints as public API
if (!FUZZ_GET_ATTR_INT(dst, "initialized")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(src, "initialized")) { FUZZ_BAIL(); }

unsigned int dst_off = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u);
unsigned int src_off = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u);
unsigned int nr      = (unsigned)(*FUZZ_PARAM(unsigned int) % 8u) + 1u;
unsigned int flags   = (unsigned)(*FUZZ_PARAM(unsigned int));

int rc = __io_uring_clone_buffers_offset(dst, src, dst_off, src_off, nr, flags);
(void)rc;

