// Prepare a small array of iovecs backed by stable storage
unsigned nr = (unsigned)(*FUZZ_PARAM(unsigned int) % 4u) + 1u;
struct iovec iov[4];
std::string backing[4];
for (unsigned i = 0; i < nr; ++i) {
    backing[i] = FUZZ_PARAM_STR();
    // Keep lengths modest
    size_t seg_len = backing[i].size() % 512u;
    if (seg_len == 0) seg_len = 1;
    iov[i].iov_base = (void*)backing[i].data();
    iov[i].iov_len  = seg_len;
}

int rc = io_uring_register_buffers(ring, iov, nr);
if (rc == 0) {
    // Track that buffers are registered
    FUZZ_SET_ATTR_INT(ring, "buffers_registered", FUZZ_GET_ATTR_INT(ring, "buffers_registered") + (int)nr);
}
(void)rc;

// Output ring for later unregister/update operations
// Validation: Provided >0 iovecs with valid backing and set attribute on success.

if (!FUZZ_GET_ATTR_INT(ring, "initialized")) { FUZZ_BAIL(); }

unsigned nr = (unsigned)(*FUZZ_PARAM(unsigned int) % 4u) + 1u;
struct iovec iov[4];
std::string backing[4];
__u64 tags[4];
for (unsigned i = 0; i < nr; ++i) {
    backing[i] = FUZZ_PARAM_STR();
    size_t seg_len = backing[i].size() % 512u; if (seg_len == 0) seg_len = 1;
    iov[i].iov_base = (void*)backing[i].data();
    iov[i].iov_len  = seg_len;
    tags[i] = ((__u64)*FUZZ_PARAM(unsigned int) << 32) | (__u64)*FUZZ_PARAM(unsigned int);
}

int rc = io_uring_register_buffers_tags(ring, iov, tags, nr);
if (rc == 0) { FUZZ_SET_ATTR_INT(ring, "buffers_registered", FUZZ_GET_ATTR_INT(ring, "buffers_registered") + (int)nr); }
(void)rc;

// Keep ring output
// Validation: Ensured nr>0 and matching tags/iovecs arrays.

if (!FUZZ_GET_ATTR_INT(ring, "initialized")) { FUZZ_BAIL(); }
